import{_ as e,o as t,c as n}from"./chunks/framework.CdjpmwdR.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","heroEyebrow":"Cognitive Model","heroTitle":"Shaping #-Type Cognition:","heroTitleHighlight":"A Core Growth Principle for Rapid Growth in the AI Era","heroDescription":"In an era where AI can increasingly replicate depth, human advantage lies in cross-domain connection and proactive exploration. Mesh (#)-shaped cognition is the structure that carries this advantage.","heroPrimaryButton":"Core Insights","heroSecondaryButton":"How to Apply","heroSecondaryButtonHref":"/en/blogs/","structureTitle":"Deconstructing the # Structure","structureDescription":"Horizontal lines represent breadth of knowledge. Vertical lines represent depth of skill. Their intersections are the decisive nodes where distinctive cognition is formed.","structureCardTitle":"Core Concept","structureCardDescription":"By linking cognitive nodes into a mesh, this model creates stable decision anchors in uncertain environments.","insightsTitleLine1":"Core","insightsTitleLine2":"Insights","insightsSubtitle":"Reframing human advantage in the AI era through repricing depth, proactive exploration, and transfer-oriented structures","insights":[{"index":"01","title":"Depth Is Being Repriced","paragraphs":["In the past, top talent was often seen as M-shaped: deep enough in two or three domains to make complex judgments independently. That level was already rare.","But AI is rapidly repricing this kind of depth. Modern models are not only broad in knowledge but also increasingly capable of reasoning, with larger context windows and lower token costs.","In minutes, AI can digest core literature in a domain and output professional-grade analyses and plans. The multi-domain depth once seen as an M-shaped edge is quickly becoming commoditized."]},{"index":"02","title":"Human Opportunity Starts with Proactive Exploration","paragraphs":["AI is knowledgeable, but it does not explore on its own. It operates within trained boundaries and cannot spontaneously ask, \\"What if we investigate an uncharted direction?\\"","Humans can. We sense where the gaps are, where tension exists, and where experiments are worth running."],"listItems":["Research: Go deep into underexplored domains and build new knowledge.","Innovation: Recombine what already exists to generate new solutions.","Transfer: Bring experience from domain A into domain B to create fast insights."]},{"index":"03","title":"#-Type Cognition Is the Structured Form of Transfer Ability","paragraphs":["Mesh (#)-shaped cognition combines breadth and depth. Two horizontal lines represent cross-domain breadth, two vertical lines represent depth in selected directions, and the intersections are where you see what others miss.","AI can help you move faster, but you still need to decide where to run. That directional judgment comes from the connection network you build across domains."]}],"ctaTitle":"People build networks, and networks connect people."},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md"}'),i={name:"en/index.md"};function o(r,a,s,d,c,h){return t(),n("div")}const u=e(i,[["render",o]]);export{p as __pageData,u as default};
